INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('003c1905-a344-58f2-8630-16281831513b', 'how-to-build-morning-skincare-routine', 'How to Build a Morning Skincare Routine', 'كيف تبني روتين العناية بالبشرة صباحاً', 'Your complete guide to building the perfect morning skincare routine for healthy, glowing skin.', 'دليلك الشامل لبناء روتين صباحي مثالي للبشرة الصحية والمشرقة.', 'A good morning routine starts with gentle cleansing, then serum, then moisturizer, and sunscreen. Choose products suitable for your skin type and follow the steps in the correct order.', 'الروتين الصباحي الجيد يبدأ بالتنظيف الخفيف ثم السيروم ثم المرطب والواقي الشمسي.', 'Dr. Fahad Al-Otaibi', 'الدكتور فهد العتيبي', NULL, 'Skincare', 'العناية بالبشرة', '/images/articles/morning-routine.svg', '2026-06-01', 5, '["morning-routine","skincare","tips"]'::jsonb, '{"title":{"ar":"كيف تبني روتين العناية بالبشرة صباحاً","en":"How to Build a Morning Skincare Routine"},"description":{"ar":"دليلك الشامل لبناء روتين صباحي مثالي.","en":"Complete guide to building the perfect morning routine."},"keywords":["morning routine","skincare","routine builder"]}'::jsonb);
