INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('e62c8560-b8d7-5494-8852-ab31cf923cdb', 'nutricosmetics-supplements-for-skin', 'Nutricosmetics Supplements for Skin', 'المكملات الغذائية للعناية بالبشرة', 'How dietary supplements can improve your skin and hair health from within.', 'كيف يمكن للمكملات الغذائية أن تحسن صحة بشرتك وشعرك من الداخل.', 'Dietary supplements like collagen, omega-3, and vitamin E can support skin and hair health from within. Consult a nutritionist before starting.', 'المكملات الغذائية مثل الكولاجين والأوميغا 3 وفيتامين E يمكن أن تدعم صحة البشرة والشعر من الداخل.', 'Dr. Fatima Ali', 'دكتورة فاطمة علي', NULL, 'Wellness', 'الصحة والعافية', '/images/articles/morning-routine.svg', '2026-07-05', 6, '["nutricosmetics","supplements","wellness"]'::jsonb, '{"title":{"ar":"المكملات الغذائية للبشرة","en":"Nutricosmetics for Skin"},"description":{"ar":"كيف تحسن صحة بشرتك بالمكملات.","en":"How supplements can improve skin health."},"keywords":["nutricosmetics","supplements","wellness"]}'::jsonb);
