INSERT INTO testimonials (id, customer_name, customer_name_ar, rating, comment, comment_ar, is_verified) VALUES ('fb0d92c5-83ff-5230-842a-08f573375bca', 'Sarah M.', 'سارة م.', 5, 'Luminous Derma transformed my skincare routine. The products are authentic and the delivery was fast!', 'لومينوس ديرما غيرت روتين العناية ببشرتي. المنتجات أصلية والتوصيل كان سريعاً!', TRUE);
INSERT INTO testimonials (id, customer_name, customer_name_ar, rating, comment, comment_ar, is_verified) VALUES ('9d99ebd1-39b7-500e-80cf-f76a401eaa33', 'Noura A.', 'نورة ع.', 5, 'I love the dermatologist recommendations section. It helped me choose the right products for my skin type.', 'أحب قسم توصيات أطباء الجلدية. ساعدني في اختيار المنتجات المناسبة لنوع بشرتي.', TRUE);
INSERT INTO testimonials (id, customer_name, customer_name_ar, rating, comment, comment_ar, is_verified) VALUES ('04122596-85a7-540c-8881-b8abb940896d', 'Mariam K.', 'مريم ك.', 5, 'Finally a trusted beauty platform in Yemen! The prices are fair and the quality is premium.', 'أخيراً منصة تجميل موثوقة في اليمن! الأسعار مناسبة والجودة ممتازة.', TRUE);
INSERT INTO testimonials (id, customer_name, customer_name_ar, rating, comment, comment_ar, is_verified) VALUES ('19f98c41-4a68-57b7-884f-9be2d95c92cf', 'Layan H.', 'ليان ه.', 4, 'Great selection of international brands. The customer service team was very helpful.', 'تشكيلة رائعة من الماركات العالمية. فريق خدمة العملاء كان مفيداً جداً.', TRUE);
INSERT INTO testimonials (id, customer_name, customer_name_ar, rating, comment, comment_ar, is_verified) VALUES ('adcfd16e-7008-56e2-82ca-5956de852f5e', 'Razan F.', 'رزان ف.', 5, 'The membership program is amazing! I love earning points on every purchase.', 'برنامج العضوية رائع! أحب جمع النقاط مع كل عملية شراء.', TRUE);
INSERT INTO faqs (id, question, answer, category) VALUES ('e5414b07-113b-5842-8545-f6be4c2d5807', '{"ar":"هل منتجاتكم أصلية 100%؟","en":"Are your products 100% authentic?"}'::jsonb, '{"ar":"نعم، جميع المنتجات المباعة في لومينوس ديرما أصلية 100%. نحن نستورد مباشرة من الموزعين المعتمدين والشركاء الرسميين للعلامات التجارية.","en":"Yes, all products sold on Luminous Derma are 100% authentic. We source directly from authorized distributors and official brand partners."}'::jsonb, 'Products');
INSERT INTO faqs (id, question, answer, category) VALUES ('cb5a1869-58f7-5598-8053-399bac277711', '{"ar":"ما هي سياسة الشحن؟","en":"What is your shipping policy?"}'::jsonb, '{"ar":"نقدم الشحن لجميع مدن اليمن. الشحن مجاني للطلبات التي تتجاوز 50,000 ريال يمني. التوصيل العادي يستغرق 3-5 أيام عمل.","en":"We offer shipping to all cities in Yemen. Free shipping is available for orders over 50,000 YER. Standard delivery takes 3-5 business days."}'::jsonb, 'Shipping');
INSERT INTO faqs (id, question, answer, category) VALUES ('cded303f-ab85-5813-8ad5-f82d1a33915a', '{"ar":"ما هي سياسة الإرجاع؟","en":"What is your return policy?"}'::jsonb, '{"ar":"حرصاً على سلامتكم، لا يمكن إرجاع أو استبدال منتجات التجميل والعناية إلا إذا وصلت تالفة. أما منتجات الأجهزة فيمكن إرجاعها بشرط أن تكون غير مستخدمة ولم تُفتح وبحالتها الأصلية.","en":"For hygiene and safety reasons, beauty and skincare products cannot be returned or exchanged unless they arrive damaged. Device products can be returned if unused, unopened, and in their original condition."}'::jsonb, 'Returns');
INSERT INTO faqs (id, question, answer, category) VALUES ('fa613cec-eb72-56c4-8d5e-28541e50fbf5', '{"ar":"كيف يعمل برنامج الولاء؟","en":"How does the loyalty program work?"}'::jsonb, '{"ar":"اجمعي نقاطاً مع كل عملية شراء ومراجعة وإحالة. يمكن استبدال النقاط بخصومات وشحن مجاني وهدايا حصرية. كما يتمتع الأعضاء بمكافآت عيد الميلاد ووصول مبكر للمنتجات الجديدة.","en":"Earn points with every purchase, review, and referral. Points can be redeemed for discounts, free shipping, and exclusive gifts. Members also enjoy birthday rewards and early access to new products."}'::jsonb, 'Loyalty');
INSERT INTO faqs (id, question, answer, category) VALUES ('26b72a1d-9f5b-5087-8538-e08886fb1dde', '{"ar":"هل يمكنني حجز استشارة طبيب جلدية؟","en":"Can I book a dermatologist consultation?"}'::jsonb, '{"ar":"نعم، نقدم استشارات عبر الإنترنت مع أطباء الجلدية. تصفحي أطباءنا المتخصصين، اختاري الوقت المناسب، واحجزي استشارتك مباشرة من خلال المنصة.","en":"Yes, we offer online dermatologist consultations. Browse our expert dermatologists, choose a convenient time slot, and book your consultation directly through the platform."}'::jsonb, 'Services');
INSERT INTO site_settings (id, key, value) VALUES ('7825e5dc-c4c8-5311-816e-2674d15b8055', 'site_config', '{"name":{"ar":"لومينوس ديرما","en":"Luminous Derma"},"tagline":{"ar":"الاختيار الصحيح","en":"The Right Choice"},"description":{"ar":"وجهة موثوقة للعناية بالبشرة والجمال في اليمن. منتجات أصلية من أشهر العلامات التجارية العالمية، مختارة بعناية لتناسب احتياجات بشرتك.","en":"A trusted destination for skincare and beauty in Yemen. Authentic products from the world''s leading brands, carefully selected to suit your skin''s needs."},"logo":"/images/logo/luminous-derma-full-logo.svg","favicon":"/favicon.ico","contact":{"phone":"+967 771 234 567","email":"hello@luminousderma.com","address":{"ar":"صنعاء، اليمن","en":"Sana''a, Yemen"}},"socialLinks":[{"platform":"instagram","url":"https://instagram.com/luminousderma","icon":"instagram"},{"platform":"tiktok","url":"https://tiktok.com/@luminousderma","icon":"tiktok"},{"platform":"snapchat","url":"https://snapchat.com/add/luminousderma","icon":"snapchat"},{"platform":"youtube","url":"https://youtube.com/@luminousderma","icon":"youtube"},{"platform":"whatsapp","url":"https://wa.me/967771234567","icon":"whatsapp"}],"businessHours":{"ar":"الأحد - الخميس: 9 صباحاً - 10 مساءً","en":"Sunday - Thursday: 9 AM - 10 PM"},"seo":{"siteName":"Luminous Derma","title":{"ar":"لومينوس ديرما - وجهتك الموثوقة للعناية بالبشرة والجمال","en":"Luminous Derma - Your Trusted Skincare and Beauty Destination"},"description":{"ar":"منتجات أصلية من أشهر العلامات التجارية العالمية، مختارة بعناية لتناسب احتياجات بشرتك في اليمن.","en":"Authentic products from the world''s leading brands, carefully selected to suit your skin''s needs in Yemen."},"keywords":["skincare","beauty","cosmetics","Yemen","luminous derma","authentic products","premium skincare"],"ogImage":"/images/og-image.svg"},"currency":"YER","currencySymbol":"ر.ي","deliveryInfo":{"ar":"توصيل لجميع محافظات اليمن","en":"Delivery to all Yemen governorates"},"paymentMethods":["Cash On Delivery","Krimi","Flosuk","Yemen Wallet","Jib","Bank Transfer"]}'::jsonb);
